const searchAuditEvents = `-- name: SearchAuditEvents :many
SELECT id, seq, at, request_id, actor_type, actor_id, action, target_type, target_id, outcome, reason_code,
  source_ip, auth_method, details_json, details_enc, prev_hash, hash
FROM audit_events
WHERE seq < ?1
  AND (?2 IS NULL OR actor_id = ?2)
  AND (?3 IS NULL OR target_id = ?3)
  AND (?4 IS NULL OR substr(action, 1, length(?4)) = ?4)
  AND (?5 IS NULL OR outcome = ?5)
  AND at >= ?6 AND at < ?7
ORDER BY seq DESC
LIMIT ?8
`

type SearchAuditEventsParams struct {
	BeforeSeq    int64
	ActorID      interface{}
	TargetID     interface{}
	ActionPrefix interface{}
	Outcome      interface{}
	Since        int64
	Until        int64
	Lim          int64
}

func (q *Queries) SearchAuditEvents(ctx context.Context, arg SearchAuditEventsParams) ([]AuditEvent, error) {
	rows, err := q.db.QueryContext(ctx, searchAuditEvents,
		arg.BeforeSeq,
		arg.ActorID,
		arg.TargetID,
		arg.ActionPrefix,
		arg.Outcome,
		arg.Since,
		arg.Until,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuditEvent{}
	for rows.Next() {
		var i AuditEvent
		if err := rows.Scan(
			&i.ID,
			&i.Seq,
			&i.At,
			&i.RequestID,
			&i.ActorType,
			&i.ActorID,
			&i.Action,
			&i.TargetType,
			&i.TargetID,
			&i.Outcome,
			&i.ReasonCode,
			&i.SourceIp,
			&i.AuthMethod,
			&i.DetailsJson,
			&i.DetailsEnc,
			&i.PrevHash,
			&i.Hash,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

